window.__saqPaperQuestions("2015-2-pah",[{"number":1,"title":"","stemText":"A 67 year old woman has been brought to the ED after falling from a second storey roof.\nAn initial chest Xray has been taken.","parts":[{"id":"a","label":"Part A","prompt":"Give the main pathology depicted on the chest x-ray. Include 4 radiographical supporting features. (5 marks) Main pathology Radiographical supporting features The patient’s vital signs are:\n\nGCS\nPulse /min\n\nBP\n70/40 mmHg\n\nRR\n/min O2 sats 99% 2L O2 via nasal prongs Xray of the pelvis is normal. FAST scan is normal. Examination reveals no long bone fractures and no open wounds. The patient cannot move her legs. The patient is awaiting CT scanning to further delineate her injuries."},{"id":"b","label":"Part B","prompt":"What is the likely cause of this patient’s hypotension? (1 mark)"},{"id":"c","label":"Part C","prompt":"Give 2 other differential diagnoses for her hypotension of traumatic aetiology.\n(2 marks) There are no significant areas of haemorrhage on CT scan."},{"id":"d","label":"Part D","prompt":"Give your management steps for her hypotension, including doses and end-points where appropriate. (3 marks)"}],"propPages":["asset:img7e5e32dc29c88acf2c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Mediastinal haematoma – likely great vessel injury</div><div class=\"answer-line\">Wide mediastinum</div><div class=\"answer-line\">Loss of aortic knob / Loss aorto-pulmonary window</div><div class=\"answer-line\">Depressed left main bronchus</div><div class=\"answer-line\">Widened right paratracheal stripe</div><div class=\"answer-line\">Left apical pleural cap</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Neurogenic shock from spine injury</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cardiac contusion / pericardial tamponade</div><div class=\"answer-line\">Retroperitoneal haemorrhage</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">End-points – systolic BP above 100mmHg, cerebral perfusion (care to avoid hypertension in</div><div class=\"answer-line\">aortic injury)</div><div class=\"answer-line\">IV N/S – 500mL-1000mL bolus repeat if necessary up to 2000mL</div><div class=\"answer-line\">Metaraminol 0.5mg aliquots, noradrenaline/adrenaline infusion 5-40 mcg/min</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 5 year old boy has been brought to the ED with anaphylaxis after eating a peanut butter\nsandwich at school.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table by listing assessment features which would suggest life- threatening anaphylaxis. Give two features in each category. (6 marks) Category Assessment Feature Airway Respiratory Cardiovascular Your assessment has confirmed life-threatening anaphylaxis involving the cardiovascular and respiratory systems. There are no signs of airway involvement. The patient’s vital signs are:\n\nGCS\nE 3 V 4 M 6\nPulse 170 /min\n\nBP\n70/45 mmHg\n\nRR\n/min O2 sats 88% room air"},{"id":"b","label":"Part B","prompt":"List your management steps in the ED. Include drug doses and end-points where appropriate. (6 marks) BLANK PAGE"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Category</td><td>Assessment Feature</td></tr><tr><td>Airway</td><td>stridor</td></tr><tr><td colspan=\"2\">Hoarse voice</td></tr><tr><td>Respiratory</td><td>Hypoxia – sats &lt;90%</td></tr><tr><td colspan=\"2\">Tiring respiratory effort</td></tr><tr><td>Cardiovascular</td><td>Hypotension &lt;80-90 systolic BP</td></tr><tr><td colspan=\"2\">Poor mentation</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Adrenaline initial 150 – 200 mcg IM (10mcg/kg), repeat if necessary Q5 min</td></tr><tr><td>-</td><td>If no response, aliquots IV 1mcg/kg (approx. 20mcg)</td></tr><tr><td>-</td><td>Nebulised also an option 5mg nebs (not essential to answer)</td></tr><tr><td>-</td><td>(2 marks total)</td></tr><tr><td colspan=\"2\">IV fluids N/S 20ml/kg bolus repeat if needed (1 mark)</td></tr><tr><td colspan=\"2\">End –points are – systolic BP greater than 90mmHg and normal mentation, also sats &gt;90-</td></tr><tr><td colspan=\"2\">92% and decreased work of breathing (2 marks)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 50 year old woman has been brought to the ED with severe chest pain of 2 hours duration. She is alert and orientated. Her ECG is given below.","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the ECG. Include ECG evidence to support your statements. (5 marks)"},{"id":"b","label":"Part B","prompt":"What is the clinical significance of these abnormalities? (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 life-threatening complications of this problem that may manifest in this patient\nin the ED. (3 marks)"},{"id":"d","label":"Part D","prompt":"List 4 factors that will determine this patient’s disposition.\n(4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">STEMI equivalent Sgarbossa criteria</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Concordant ST elevation (I, avL)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Excessively discordant ST elevation &gt;5mm (V2 V3) (2 marks)</div><div class=\"answer-line\">Hyperacute tall T waves anterior leads (V2-V4) (1 mark)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">STEMI equivalent, requires urgent re-perfusion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Arrhythmias – tachy VT / VF, brady heart blocks</div><div class=\"answer-line\">LVF / APO</div><div class=\"answer-line\">Cardiogenic shock with hypotension and poor end-organ perfusion</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Availability of cath lab within 90 min door to balloon time (one category encompassing all</div><div class=\"answer-line\">excuses here)</div><div class=\"answer-line\">Contra-indications to thrombolysis</div><div class=\"answer-line\">Presence of shock/complications – cath lab only good option</div><div class=\"answer-line\">Pt consent</div><div class=\"answer-line\">Local protocols</div><div class=\"answer-line\">Allergies</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"Your director has asked you to develop a protocol for managing high risk chest pain in the Emergency Department.","parts":[{"id":"a","label":"Part A","prompt":"List the steps you would undertake in developing this protocol. (6 marks)"},{"id":"b","label":"Part B","prompt":"List ten high risk chest pain features as per the National Heart Foundation of Australia and New Zealand. (10 marks) BLANK PAGE"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Current processes</td></tr><tr><td>-</td><td>Guidelines College</td></tr><tr><td>-</td><td>Other hospitals</td></tr><tr><td colspan=\"2\">Liaise stakeholders (2 marks)</td></tr><tr><td>-</td><td>ED consultants / nurses</td></tr><tr><td>-</td><td>Cardiologists</td></tr><tr><td colspan=\"2\">Write protocol</td></tr><tr><td colspan=\"2\">Audit performance (1 mark)</td></tr><tr><td colspan=\"2\">Re-evaluate (1 mark)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Prolonged or repetitive pain</div><div class=\"answer-line\">Raised biomarkers</div><div class=\"answer-line\">ECG changes – ST depression &gt;0.5mm / TWI &gt;2mm</div><div class=\"answer-line\">transient ST elevation</div><div class=\"answer-line\">VT</div><div class=\"answer-line\">Shock</div><div class=\"answer-line\">Syncope</div><div class=\"answer-line\">DM</div><div class=\"answer-line\">Renal failure</div><div class=\"answer-line\">PCI 6/12 or CABG ever</div><div class=\"answer-line\">EF &lt;40%</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 60 year old woman has presented to the ED with a 2 day history of shortness of breath and cough. Her chest x-ray is given below.","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the chest x-ray, including the radiographic supporting evidence. (5 marks)"},{"id":"b","label":"Part B","prompt":"Give your interpretation of the Xray findings. (2 marks)\nHer vital signs are:\n\nGCS\nPulse 120 /min\n\nBP\n100/60 mmHg\n\nRR\n/min O2 sats 88% room air Temperature 38.5 degrees"},{"id":"c","label":"Part C","prompt":"List your treatment steps. Give details of your doses and end-points where appropriate. (5 marks)"}],"propPages":["asset:img111337c33983f65b77"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left hilar mass – rounded opacity left hilum</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Some patchy consolidation around this area</div><div class=\"answer-line\">Confluent consolidation right upper lobe bordered by horizontal fissure</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Air bronchograms</div><div class=\"answer-line\">Patchy consolidation right lower zone as well – right middle lobe as part of right cardiac</div><div class=\"answer-line\">border obscured</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Multi-lobar pneumonia</div><div class=\"answer-line\">Left hilar mass likely malignancy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">O2 – titrate to keep sats &gt;92%</div><div class=\"answer-line\">IV fluids – 500 – 1000mL stat aiming for pulse &lt;100, BP &gt;100</div><div class=\"answer-line\">IV antibiotics for severe CAP</div><div class=\"answer-line\">Either – ceftriaxone 1g and azithromycin 500mg</div><div class=\"answer-line\">Or – amp/ben-pen, gentamicin 5 - 7mg/kg, azithromycin 500mg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 65 year old woman has been brought to the ED with abnormal behaviour. She had been\nfound wandering in the street yelling, “They are trying to get me!”. She is known to have schizophrenia. She is unable to give any coherent history.","parts":[{"id":"a","label":"Part A","prompt":"List 5 findings of your examination that would suggest delirium to be the cause of her\npresentation. (5 marks)"},{"id":"b","label":"Part B","prompt":"List 3 pieces of collateral history that would suggest psychosis to be the primary\nproblem. (3marks) While being assessed, the patient becomes very agitated and attempts to leave. Assessment so far has suggested that the patient is incapable of making rational decisions."},{"id":"c","label":"Part C","prompt":"List the management steps, in sequential order, that you would use to ensure the patient remains in the ED. Give brief details of each step. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Abnormal vital signs (Fever, tachycardia, hypotension)</div><div class=\"answer-line\">Disorientation</div><div class=\"answer-line\">Inability to attend (concentration)</div><div class=\"answer-line\">Signs of infection – eg crackles, tender abdomen</div><div class=\"answer-line\">Neurological signs</div><div class=\"answer-line\">-many other possibilities</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Failure to take medications</div><div class=\"answer-line\">Similar presentation to previous exacerbations schizophrenia</div><div class=\"answer-line\">Gradual deterioration</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Call security</div><div class=\"answer-line\">Attempt verbal de-escalation</div><div class=\"answer-line\">Oral sedation – diazepam 5mg</div><div class=\"answer-line\">If not successful then</div><div class=\"answer-line\">Physical restraint – 5 point with security</div><div class=\"answer-line\">-</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Chemical restraint – droperidol 5-10mg IM / IV</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"You are part of a helicopter retrieval team tasked to retrieve a patient from the scene of a high speed motor vehicle accident. When you arrive on scene, you find the patient to be lying supine on the road.","parts":[{"id":"a","label":"Part A","prompt":"List 5 possible indications for intubation of this patient prior to loading him on to the\nhelicopter. (5 marks) Upon your arrival, the patient becomes unresponsive to painful stimulus. There are no palpable pulses. ECG monitoring demonstrates sinus rhythm with a rate of 120 beats per minute."},{"id":"b","label":"Part B","prompt":"List your immediate actions. (4 marks) Your initial actions restore a perfusing circulation."},{"id":"c","label":"Part C","prompt":"List the important components of your fluid resuscitation strategy, assuming there is no clear evidence of head injury. (3 marks) BLANK PAGE"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Head injury with LOC / anticipated LOC</div><div class=\"answer-line\">Profound shock</div><div class=\"answer-line\">Respiratory failure from chest injury</div><div class=\"answer-line\">High spinal cord injury – ineffective ventilation</div><div class=\"answer-line\">Severe pain / agitation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">CPR</div><div class=\"answer-line\">Bilateral chest decompression</div><div class=\"answer-line\">Intubation with 100% O2</div><div class=\"answer-line\">Blood administration</div><div class=\"answer-line\">Application of pelvic binder</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Blood products only (aim 1:1 – 1:2 packed cells : FFP if available)</div><div class=\"answer-line\">Goals – systolic BP 80mmHg, radial pulse</div><div class=\"answer-line\">Minimise crystalloid</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 28 year old man with type 1 diabetes has presented to the ED with vomiting for 2 days.\nHis venous blood gas is given below. Venous blood gas\n\npH\n7.41 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (18 - 26)\n\nBE\n2.2 mmol/L (-3 - +3)\n\nNa\n132 mmol/L (135 - 145)\n\nK\n5.1 mmol/L (3.5 - 4.5)\n\nCl\nmmol/L (100 - 110)\n\nGlucose\nmmol/L (3.0 - 7.8)\n\nLactate\n3.0 mmol/L (0.5 - 2.2)\n\nCreatinine\n367 umol/L (73 - 108)","parts":[{"id":"a","label":"Part A","prompt":"Give the abnormalities on the blood gas, including likely causes of each abnormality identified. (8 marks) The patient’s vital signs are:\n\nGCS\nPulse 120 /min\n\nBP\n100/70 mmHg\n\nRR\n/min O2 sats 99% room air"},{"id":"b","label":"Part B","prompt":"List your management steps. Include doses and end-points where appropriate. (8 marks) BLANK PAGE"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">High anion gap metabolic acidosis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">AG 29</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Due to DKA (high BSL) with contributions from renal failure and lactic acidosis</div><div class=\"answer-line\">Concomitant metabolic alkalosis due to vomiting</div><div class=\"answer-line\">= resultant normal pH</div><div class=\"answer-line\">Hyperkalaemia due to renal failure</div><div class=\"answer-line\">High lactate – likely type A from shock, but component type B from renal failure</div><div class=\"answer-line\">High creat – renal failure (pre-renal with illness, CRF from DM)</div><div class=\"answer-line\">Na low, but when corrected for BSL is upper normal – 144-145</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Insulin infusion Actrapid 5U/hr – end-point resolution of ketosis</div><div class=\"answer-line\">IV fluids – N/S (bolus acceptable 1000mL stat) initially 1 litre over 1 hour then replace losses</div><div class=\"answer-line\">plus maintenance over 24-48hrs, add 5% dextrose when BSL falls to 12-15, maintain BP</div><div class=\"answer-line\">&gt;100mmHg and cerebral perfusion</div><div class=\"answer-line\">K replacement – will fall with insulin – add 40mmol/L to infusion when K falls to 4.5 – 5.0</div><div class=\"answer-line\">only if passing urine (care with chronic renal failure)</div><div class=\"answer-line\">Treat cause (eg sepsis, abdominal pathology)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"An 18 month old boy has been brought to the ED with a rash.\nHis clinical photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Provide a description of the clinical photograph. (4 marks)"},{"id":"b","label":"Part B","prompt":"List your 5 main differential diagnoses.\n(5 marks)"},{"id":"c","label":"Part C","prompt":"List and justify the 4 investigations you may perform on this child to elucidate the\ncause of the rash. (4 marks)"}],"propPages":["asset:imgabad135ca34de409ed"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Alert Caucasian child</td></tr><tr><td colspan=\"2\">Widespread rash – face, ears, neck torso</td></tr><tr><td>-</td><td>Erythematous</td></tr><tr><td>-</td><td>Macular</td></tr><tr><td>-</td><td>Areas confluence</td></tr><tr><td>-</td><td>Less prevalent dorsum of right hand pictured</td></tr><tr><td>-</td><td>Circumoral sparing – pallor</td></tr><tr><td>-</td><td>Dry lips/tongue/mucous membranes</td></tr><tr><td colspan=\"2\">No conjunctivitis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Measles</div><div class=\"answer-line\">Other viral illness eg rubella</div><div class=\"answer-line\">Urticarial – allergy, other</div><div class=\"answer-line\">Drug rash</div><div class=\"answer-line\">Scarlet fever</div><div class=\"answer-line\">Erythema multiforme</div><div class=\"answer-line\">Kawasaki disease</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Measles PCR – nasopharyngeal swab</div><div class=\"answer-line\">Tests for Strep</div><div class=\"answer-line\">throat swab culture</div><div class=\"answer-line\">-</div><div class=\"answer-line\">-</div><div class=\"answer-line\">blood for ASOT / anti DNAase B</div><div class=\"answer-line\">inflammatory markers if Kawasaki disease suspected – CRP, ESR</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 24 year old man has presented to the ED with a severe headache.\nHe underwent revision of a ventriculo-peritoneal (VP) shunt 5 days ago in your hospital.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses that you would consider related to his VP shunt.\n(4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 investigations you could use to determine the presence of the above diagnoses.\nFor each investigation, give the abnormality for which you would be looking. (6 marks) Investigation Abnormality"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Blocked shunt – hydrocephalus</div><div class=\"answer-line\">Fractured shunt – hydrocephalus</div><div class=\"answer-line\">Meningo-encephalitis</div><div class=\"answer-line\">Wound infection</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Investigation</td><td>Abnormality</td></tr><tr><td>CT head</td><td>Hydrocephalus</td></tr><tr><td>Shunt series x-ray</td><td>Fractured shunt</td></tr><tr><td>LP / shunt tap</td><td>Raised WCC – meningo-encephalitis</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 32 year old G3 P2 woman has presented to your ED with a headache. She is 38 weeks\npregnant. You are concerned that she may have pre-eclampsia.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your examination that would support this diagnosis.\n(4 marks)"},{"id":"b","label":"Part B","prompt":"List 5 investigations you would request, including the results that would be suggestive\n• f complications related to pre-eclampsia.\n(5 marks) You have diagnosed pre-eclampsia. After a brief time in your ED, she has a generalised seizure."},{"id":"c","label":"Part C","prompt":"List your management steps, including drugs, doses and end-points where appropriate. (5 marks) BLANK PAGE"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hypertension &gt;140/90 mmHg or rise &gt;30/15 mmHg from baseline</div><div class=\"answer-line\">Significant peripheral oedema</div><div class=\"answer-line\">Hyper-reflexia</div><div class=\"answer-line\">Tender hepatomegaly</div><div class=\"answer-line\">Papilloedema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Urate – elevated</div><div class=\"answer-line\">Urea/creat – acute renal failure</div><div class=\"answer-line\">Platelets – low in HELLP</div><div class=\"answer-line\">LFTS – raised in HELLP</div><div class=\"answer-line\">Coags – DIC</div><div class=\"answer-line\">CTG monitoring – all patients to determine fetal distress / viability</div><div class=\"answer-line\">Hb – low in haemolysis in HELLP</div><div class=\"answer-line\">Urine protein</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Seizure management – O2, positioning etc</div><div class=\"answer-line\">Magnesium 20mmol slow push then 5mmol/hr – end point hypo-reflexia</div><div class=\"answer-line\">Seizure termination with midazolam/diazepam 2.5 – 5mg</div><div class=\"answer-line\">BP management – Mg as above – then other – hydralazine 5-10mg IV, aim BP &lt;140/90</div><div class=\"answer-line\">Arrange Obstetric review for delivery</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 57 year old woman has been brought to the ED after falling while dancing. She has an\nisolated left ankle injury. There are no wounds. Her x-rays are shown.","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the x-ray. Include your interpretation of the abnormalities. (6 marks)"},{"id":"b","label":"Part B","prompt":"List your management steps, including details. (4 marks)"}],"propPages":["asset:imgbe5822143b37be37c5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Medial malleolar fracture tibia</div><div class=\"answer-line\">Weber B fibula fracture – at level of syndesmosis (2 marks)</div><div class=\"answer-line\">Lateral talar displacement</div><div class=\"answer-line\">“posterior malleolar fracture” posterior tibia</div><div class=\"answer-line\">Interpretation – unstable ankle fracture requiring ORIF</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia – morphine 2.5mg aliquots</div><div class=\"answer-line\">Plaster under procedural sedation</div><div class=\"answer-line\">Short leg backslab</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Elevation limb - pillow</div><div class=\"answer-line\">Orthopaedic admission for ORIF</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 30 year old man presents to your ED with palpitations and shortness of breath.\nHis ECG is shown on the next page.","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormalities on the ECG with supportive evidence. (6 marks)\nHis vital signs are:\n\nGCS\nE 4 V 4 M 6\n\nBP\n75/45 mmHg\n\nRR\n/min O2 sats 99% 6L O2 via face mask"},{"id":"b","label":"Part B","prompt":"List your management steps. Include specific drugs and doses where appropriate. (5 marks)"}],"propPages":["asset:imgb791ada18376b73f84"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Rhythm irregularly irregular – atrial fibrillation</div><div class=\"answer-line\">Ventricular rate variable – approx. 200-250/min – very fast</div><div class=\"answer-line\">Left ward axis of broad complexes</div><div class=\"answer-line\">2 types QRS complex – narrow and broad (mostly) – represent different pathways of</div><div class=\"answer-line\">activation of ventricles – narrow through AV node, broad through accessory pathway</div><div class=\"answer-line\">Hence AF with rapid ventricular response in pt with accessory pathway (WPW)</div><div class=\"answer-line\">Delta wave seen best in V4</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Pt needs emergent cardioversion</td></tr><tr><td>-</td><td>Consent / explanation</td></tr><tr><td>-</td><td>Small aliquots of sedation (eg midazolam 1mg boluses titrated to light sedation) 2</td></tr><tr><td colspan=\"2\">marks</td></tr><tr><td>-</td><td>DC cardioversion synchronized 200J</td></tr><tr><td>-</td><td>Optimise electrolytes – K, Mg</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 2 week old boy has been brought to your ED by his mother.\nHe has been noted to be pale, floppy and less responsive than usual.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table by giving 5 differential diagnoses for his presentation, with 2 cardinal examination findings that would suggest each"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Sepsis</td><td>fever</td></tr><tr><td colspan=\"2\">Focal signs infection eg crackles, cellulitis, fontanelle</td></tr><tr><td>Cardiac failure/ congenital</td><td>Heart murmur, hepatomegaly</td></tr><tr><td colspan=\"2\">heart disease</td></tr><tr><td colspan=\"2\">Cyanosis not responding to O2</td></tr><tr><td>Abdominal catastrophe</td><td>Tender abdomen, abdominal distension</td></tr><tr><td colspan=\"2\">Inguinal hernia</td></tr><tr><td>NAI</td><td>Multiple bruises, burns</td></tr><tr><td colspan=\"2\">Retinal haemorrhages</td></tr><tr><td>Metabolic</td><td>Virilisation, syndromic appearance</td></tr><tr><td colspan=\"2\">Hyperpigmentation, hepatosplenomegaly</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 44 year old man has presented with pain and swelling under his jaw.\nHis clinical photo is shown.","parts":[{"id":"a","label":"Part A","prompt":"List 3 important abnormalities in the clinical photo.\n(3 marks)"},{"id":"b","label":"Part B","prompt":"Give your interpretation of the photograph. (2 marks) On examination, the patient has the following vital signs:\n\nGCS\nPulse 120 /min\n\nBP\n100/65 mmHg\n\nTemp\n38.5 degrees\n\nRR\n/min O2 saturation 99% room air He can only open his mouth to allow one finger between his incisors."},{"id":"c","label":"Part C","prompt":"List your priorities for this patient’s management, including details of drugs and doses where appropriate. (6 marks)"}],"propPages":["asset:img875b1aeffe925de8c2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Erythema under mandible</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Extends to anterior chest wall</div><div class=\"answer-line\">Swelling below mandible on the right side</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ludwig’s angina (submandibular abscess)</div><div class=\"answer-line\">Cellulitis extending to anterior chest wall</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – IV morphine 2.5mg aliquots (or similar)</div><div class=\"answer-line\">IV antibiotics – ampicillin 1g, metronidazole 500mg</div><div class=\"answer-line\">IV fluids – bolus N/S 1000mL aiming for pulse &lt;100</div><div class=\"answer-line\">Airway management – fibre-optic intubation in theatre anaesthetics</div><div class=\"answer-line\">Imaging – CT neck/chest to look for abscess</div><div class=\"answer-line\">ENT surgical referral for drainage collections</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 45 year old man presents following an overdose of verapamil tablets.","parts":[{"id":"a","label":"Part A","prompt":"List 6 important features of your toxicological history.\n(6 marks) After a brief period in the ED, his vitals signs are:\n\nGCS\nE 3 V 3 M 5\nPulse /min\n\nBP\n75/45 mmHg\n\nRR\n/min O2 sats 100% 6L O2 via mask"},{"id":"b","label":"Part B","prompt":"List your management steps. Include drugs, doses and end-points where appropriate. (10 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Time ingestion</div><div class=\"answer-line\">Formulation - SR</div><div class=\"answer-line\">Ingested dose</div><div class=\"answer-line\">Self-decontamination ie vomiting since ingestion</div><div class=\"answer-line\">Other co-ingestants</div><div class=\"answer-line\">Co-morbidities that will impact ability to compensate</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Atropine 1mg IV repeat to 3mg</div><div class=\"answer-line\">Insulin / dextrose – 50U bolus insulin then 50U/hr, dex 50mL 50% bolus then 50ml 50%/hr</div><div class=\"answer-line\">via CVL (1 mark)</div><div class=\"answer-line\">Early intubation (1 mark)</div><div class=\"answer-line\">Administration of charcoal 1g/kg when intubated (not before) (1 mark)</div><div class=\"answer-line\">(consideration of electrical pacing if still not achieving adequate perfusion) (1 mark)</div><div class=\"answer-line\">ICU referral (1 mark)</div><div class=\"answer-line\">End points (2 marks)</div><div class=\"answer-line\">haemodynamic – pulse &gt;50/min, MAP &gt;65mmHg</div><div class=\"answer-line\">-</div><div class=\"answer-line\">-</div><div class=\"answer-line\">ionised Ca – 2.0mmol/L</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 52 year old woman has been brought to the ED with right sided upper and lower limb\nweakness. Your provisional diagnosis is a left middle cerebral artery territory ischaemic stroke.","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnoses for this presentation.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List 3 relevant investigations you would do on this patient. Include the results for\nwhich you will be looking. (3 marks) Test Relevant Finding Your assessment is consistent with the diagnosis of ischaemic stroke."},{"id":"c","label":"Part C","prompt":"List 4 examination findings that would exclude this patient from being eligible for\nthrombolysis. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Haemorrhagic stroke / ICH</div><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">Migraine</div><div class=\"answer-line\">Todd’s paresis</div><div class=\"answer-line\">Intracranial tumour</div><div class=\"answer-line\">Intracranial abscess</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">BSL – exclude hypoglycaemia</div><div class=\"answer-line\">CT head – for haemorrhage</div><div class=\"answer-line\">ECG – for AF</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">NIHSS &lt;=4  or &gt;=24</div><div class=\"answer-line\">Resolving signs</div><div class=\"answer-line\">Evidence of active bleeding or acute trauma</div><div class=\"answer-line\">Systolic BP &gt;180mmHg, diastolic &gt;110mmHg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"You are the consultant in charge of the emergency department on a Sunday evening. You have a number of admitted patients in your department awaiting placement to an inpatient ward. All of your acute and resuscitation treatment spaces are full. The ambulance service has called to advise they are bringing an unstable patient with a gunshot wound to the abdomen from a property 20 minutes away.","parts":[{"id":"a","label":"Part A","prompt":"List 3 actions you could undertake within the ED to accommodate the inbound\npatient. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 2 actions you would suggest to the hospital executive to minimise ongoing\naccess block issues in the evening. (2 marks)"},{"id":"c","label":"Part C","prompt":"Provide 3 strategies such a facility could introduce to avoid similar access block\nissues on the weekend. For each strategy, please list 2 specific points on how the strategy might be implemented. (9 marks)\nStrategy 1\nDetails 1. 2.\nStrategy 2\nDetails 1. 2.\nStrategy 3\nDetails 1. 2."}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Expedite admissions</div><div class=\"answer-line\">• Expedite / sit out discharges or low acuity patients</div><div class=\"answer-line\">• Plan to move patient direct to OT for management</div><div class=\"answer-line\">• Move patients to short stay (if available)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Over census</div><div class=\"answer-line\">• Open decommissioned / non-staffed / unfunded bed spaces</div><div class=\"answer-line\">• Utilise other treatment areas – day procedure, recovery, transit lounge,</div><div class=\"answer-line\">radiology holding area</div><div class=\"answer-line\">• Immediate audit of bed stock – identify empty beds not previously identified</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Strategy</td><td>Details (2 specific points)</td></tr><tr><td>Maximise weekend</td><td>Friday multi disciplinary meets to plan discharges; Post</td></tr><tr><td>discharges</td><td>take consultant WR for all teams</td></tr><tr><td>Extended hours hospital</td><td>Hospital in the home programs; RAFC outreach</td></tr><tr><td>avoidance strategies</td><td>programs; Acute community based psychiatric teams;</td></tr><tr><td>Day hospital; Step down facilities</td><td></td></tr><tr><td>Optimise week:weekend</td><td>Long stay admissions planned for early in the week;</td></tr><tr><td>bed utilisation</td><td>Bed utilisation predictive tools</td></tr><tr><td>Early escalation strategies</td><td>Anticipate excess load with triggers at ambulance, ED</td></tr><tr><td>and hospital levels; Load sharing with adjacent towns</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 25 year old man had been brought to the ED after being assaulted with a baseball bat.\nAssessment reveals isolated head injuries. An image from his CT head scan is given.","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the CT scan. (6 marks) After a short period in the ED, his vital signs are: GSC\nE 2 V 3 M 5\nPulse 100 /min\n\nBP\n140/70 mmHg\n\nRR\n/min O2 sats 99% 6L O2 via mask"},{"id":"b","label":"Part B","prompt":"List your management priorities. Include details of your drugs, doses and end- points. (9 marks) BLANK PAGE"}],"propPages":["asset:imgfc82b8f9faf48fd89b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left scalp haematoma</div><div class=\"answer-line\">Left extradural haematoma (2 marks for the details)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Acute (hyperdense)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Swirl sign (decreased density in dense area indicative of rapid bleeding)</div><div class=\"answer-line\">Left parietal contusion</div><div class=\"answer-line\">Midline shift to right</div><div class=\"answer-line\">Loss of sulci due to mass effect</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Facilitate urgent neurosurgery (1 mark)</td></tr><tr><td colspan=\"2\">End points (3 marks)</td></tr><tr><td>-</td><td>MAP &gt;75mmHg</td></tr><tr><td>-</td><td>O2 sats &gt;90%</td></tr><tr><td>-</td><td>CO2 35-40mmHg</td></tr><tr><td colspan=\"2\">Secondary measures (max 3 marks this group)</td></tr><tr><td>-</td><td>Normothermia</td></tr><tr><td>-</td><td>Normoglycaemia</td></tr><tr><td>-</td><td>Head up</td></tr><tr><td>-</td><td>Na high normal</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 72 year old woman has presented with abdominal pain and fever of 2 days duration.\nSome of her blood results are given below.\n\nNa\n125 mmol/L (135 - 145)\n\nK\n4.4 mmol/L (3.5 - 5.1)\n\nCl\nmmol/L (100 - 110)\n\nHCO3\nmmol/L (22 - 32)\n\nGlucose\n7.5 mmol/L (3.0 - 7.8)\n\nUrea\n23.7 mmol/L (2.9 - 8.2)\n\nCreatinine\n219 mmol/L (64 - 108) Protein g/L (60 - 83) Albumin g/L (35 - 50) Bilirubin 255 umol/L (<20) Bili (conj) 198 umol/L (<4) ALP 867 U/L (56 - 119) Gamma GT 412 U/L (<55) ALT 178 U/L (<45) AST 153 U/L (<35) CK U/L (46 - 171)","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities with likely explanations. (7 marks)"},{"id":"b","label":"Part B","prompt":"Give your overall clinical interpretation. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Renal failure</td></tr><tr><td>-</td><td>Possible lactate from hypoperfusion ( 1 mark total DDx)</td></tr><tr><td>Renal failure – urea/creat suggestive pre-renal – hypoperfusion</td><td>(1 mark)</td></tr><tr><td colspan=\"2\">Low albumin / normal total protein – acute phase response sepsis (1 mark)</td></tr><tr><td>High bilirubin predominantly conjugated – biliary obstruction</td><td>(1 mark)</td></tr><tr><td>LFTS obstructive pattern (GGT and ALP)</td><td>(1 mark)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ascending cholangitis with biliary obstruction</div><div class=\"answer-line\">Sepsis</div><div class=\"answer-line\">End-organ hypoperfusion / shock / dehydration</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"An 18 month old boy has been brought to your ED with vomiting and abdominal distension.\nHis abdominal x-ray is given below.","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the x-ray, including your interpretation. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 2 methods of definitive management of this problem.\n(2 marks) The patient looks pale. His vital signs are: Alert Pulse 160 /min\n\nBP\n90/40 mmHg\n\nRR\n/min O2 sats 99% room air"},{"id":"c","label":"Part C","prompt":"List your 3 main management steps, including details.\n(3 marks)"},{"id":"d","label":"Part D","prompt":"List 3 complications of this condition.\n(3 marks)"}],"propPages":["asset:img19c4115b9bb1e949c0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Intussusception</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Dilated transverse colon with crescent side RUQ (intussusceptum)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Small bowel gas present centrally</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Air enema</div><div class=\"answer-line\">Surgical management</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV fluid bolus N/S 20ml/kg</div><div class=\"answer-line\">Analgesia – morphine 0.05 - 0.1mg/kg IV (or something else acceptable)</div><div class=\"answer-line\">Urgent arrangement of definitive management</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bowel obstruction</div><div class=\"answer-line\">Perforation</div><div class=\"answer-line\">Intestinal ischaemia</div><div class=\"answer-line\">Haemorrhage / GI bleeding</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 32 year old man has been found unconscious in a park during winter.\nOn arrival to the ED, he has:\n\nGCS\nE 3 V 3 M 5\n\nTemp\n29.5 degrees","parts":[{"id":"a","label":"Part A","prompt":"List 6 possible causes (aside from hypothermia) for his reduced level of\nconsciousness. (6 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table indicating the expected pathophysiological effects of hypothermia. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 5 methods of rewarming a hypothermic patient. For each method provide the\nclinical triggers for its use. (10 marks) Method Clinical Triggers"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Trauma – head injury</div><div class=\"answer-line\">Intoxication – eg alcohol</div><div class=\"answer-line\">Metabolic – hypoglycaemia</div><div class=\"answer-line\">Hypoxia – respiratory disease eg pneumonia</div><div class=\"answer-line\">Hypercapnoea</div><div class=\"answer-line\">CNS infection – encephalitis</div><div class=\"answer-line\">Other possibilities</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">2.</div><div class=\"answer-line\">Body system</div><div class=\"answer-line\">Cardiovascular</div><div class=\"answer-line\">hypotension</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Method</td><td>Clinical Triggers</td></tr><tr><td>Passive external – blankets,</td><td>All hypothermic patients, &lt;35 degrees</td></tr><tr><td>warm air</td><td></td></tr><tr><td>Warm IV fluids</td><td>All hypothermic patients, &lt;35 degrees</td></tr><tr><td>Warm bladder lavage</td><td>Where IDC is indicated, symptomatic hypothermia</td></tr><tr><td>Gastric lavage - warm</td><td>Intubated patients only</td></tr><tr><td>Pleural lavage</td><td>Cardiac arrest</td></tr><tr><td>Bypass / ECMO</td><td>Cardiac arrest</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 30 year old man has been brought to the ED after falling down a staircase while\nintoxicated with alcohol. He was intubated on scene due to a decreased level of consciousness. He has no pre-existing medical problems. Your registrar is having trouble ventilating the patient. The ventilator is sounding an alarm for high airway pressures and terminating inspiration at 150mL tidal volume each breath. You suspect that the patient has significant aspiration lung injury.","parts":[{"id":"a","label":"Part A","prompt":"List 5 other potential causes for this problem.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List your initial actions that will determine the cause of the problem. (5 marks) You have determined that severe aspiration lung injury is the cause of the problem. The patient’s current vital signs are: Pulse 110 /min\n\nBP\n110/70 mmHg O2 saturations 88% Arterial blood gas has shown:\n\npO2\nmmHg\n\npCO2\nmmHg The patient’s current ventilator settings are: Volume control\n\nFiO2\n1.0 TV 500 mL\n\nRR\n/min PEEP cm H2O Pressure limit cm H2O"},{"id":"d","label":"Part D","prompt":"List 3 changes to the ventilator settings that will improve the patient’s oxygenation.\nFor each change, give a potential adverse effect of the change. (6 marks) Change in ventilator setting Potential adverse effect"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["E ratio 1:2"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Examine for tension pneumothorax</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">3.</div><div class=\"answer-line\">Change in ventilator setting</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Increase PEEP</td><td>Hypotension, may decrease tidal volume</td></tr><tr><td>Risk barotrauma eg pneumothorax, ARDS</td><td></td></tr><tr><td>Increase pressure limit</td><td></td></tr><tr><td>Potential worsen hypercapnoea if bronchospasm</td><td></td></tr><tr><td>Increase I time / decrease I:E</td><td></td></tr><tr><td>ratio</td><td></td></tr><tr><td>NOT ACCEPT – increase TV (this is not being reached), increase RR (unlikely to improve</td><td></td></tr><tr><td>oxygenation)</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"An 68 year old man has presented to the ED with severe chest pain, radiating to his back.\nYou are concerned about the possibility of an aortic dissection.","parts":[{"id":"a","label":"Part A","prompt":"Give 2 diagnostic modalities for confirming the diagnosis. For each, outline the\nclinical circumstances where you would choose the modality. (4 marks) Modality Clinical use Modality Clinical use A Stanford type A aortic dissection has been confirmed on imaging."},{"id":"b","label":"Part B","prompt":"List your management priorities. Where relevant, give doses and end-points. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 4 life-threatening complications that might become evident in the ED.\n(4 marks) BLANK PAGE"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>CT angiogram</td><td></td></tr><tr><td>-</td><td>Preferable study, contra-indicated with allergy to contrast, inability to tolerate CT or</td></tr><tr><td>relative C/I in renal failure</td><td></td></tr><tr><td>Echo</td><td></td></tr><tr><td>-</td><td>Only use if unable to perform CT for above reasons</td></tr><tr><td>-</td><td>TTE not very sensitive, TOE better, less available</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">BP control</td></tr><tr><td>-</td><td>Aim systolic BP 100-110mmHg (1 mark)</td><td></td></tr><tr><td>-</td><td>Metoprolol IV 2mg aliquots until BP target or HR 60 (1 mark)</td><td></td></tr><tr><td>-</td><td>Then vasodilatation – eg GTN infusion, SNP or hydralazine (1 mark)</td><td></td></tr><tr><td colspan=\"3\">Analgesia</td></tr><tr><td>-</td><td>Morphine 2.5 mg aliquots</td><td>(1 mark)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pericardial tamponade</div><div class=\"answer-line\">Stroke</div><div class=\"answer-line\">Severe AR</div><div class=\"answer-line\">MI</div><div class=\"answer-line\">(other vital organ ischaemia due to dissected branch)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 22 year old labourer has re-presented to your ED with a painful right elbow after a fall on\nto his out-stretched hand 4 days prior. He was seen in the ED after the accident and\ndischarged with the diagnosis of a “sprained elbow”. He was provided with appropriate analgesia. The x-ray below was taken on his initial presentation.","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the x-ray. (3 marks)"},{"id":"b","label":"Part B","prompt":"What is the clinical significance of the situation? (2 marks) The patient is angry and wishes to make a complaint."},{"id":"c","label":"Part C","prompt":"List 7 key steps in your management of this situation.\n(7 marks)"}],"propPages":["asset:img1f3574a780c3015060"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Swollen anterior fat pad (sail sign)</div><div class=\"answer-line\">Swollen posterior fat pad</div><div class=\"answer-line\">Undisplaced radial head fracture anterior aspect radial head</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Missed fracture</div><div class=\"answer-line\">Minimal clinical significance as this injury is treated conservatively and with early</div><div class=\"answer-line\">mobilisation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Apologise for situation</div><div class=\"answer-line\">Explain clinical significance</div><div class=\"answer-line\">Facilitate formal complaint if patient wishes</div><div class=\"answer-line\">Arrange appropriate clinical care – follow up orthopaedics, analgesia, sling, physio</div><div class=\"answer-line\">Investigate missed fracture – systems, staff, processes</div><div class=\"answer-line\">Notify staff involved</div><div class=\"answer-line\">Education where required</div><div class=\"answer-line\">Processes to be adjusted where needed eg senior staff supervision / Xray checks</div><div class=\"answer-line\">(other steps likely to be acceptable)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 78 year old man has presented to the ED with general malaise and several episodes of\nsyncope. He has a history of type 2 diabetes with complications of ischaemic heart disease, chronic renal failure and peripheral vascular disease. His ECG is shown.","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the ECG. Include your overall interpretation. (5 marks) The patient’s vital signs are:\n\nGCS\n\nBP\n100/60 mmHg\n\nRR\n/min O2 sats 95% 2L O2 via nasal prongs He has evidence of mild pulmonary oedema on examination."},{"id":"b","label":"Part B","prompt":"List your ED treatment steps based on the clinical information. Include details of drugs and doses where appropriate. (7 marks)"}],"propPages":["asset:img9ca3ae694011bb68ae"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1.</div><div class=\"answer-line\">Pacing spikes – ventricular pacing rate about 70 (1 mark)</div><div class=\"answer-line\">Very broad QRS, almost sine wave (1 mark)</div><div class=\"answer-line\">Tall/broad T waves (1 mark)</div><div class=\"answer-line\">Consistent with severe (1 mark) hyperkalaemia in a paced pt (1 mark)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Treat hyperK</td></tr><tr><td>-</td><td>Ca gluconate 10% 20-30mL</td><td></td></tr><tr><td>-</td><td>Insulin 10U actrapid / dextrose 50mL 50%</td><td></td></tr><tr><td>-</td><td>Na HCO3</td><td>- 100mmol</td></tr><tr><td>-</td><td>Salbutamol nebs 5mg</td><td></td></tr><tr><td>-</td><td>(resonium 30g)</td><td></td></tr><tr><td>-</td><td>Diuretics frusemide (reasonable dose)</td><td></td></tr><tr><td>-</td><td>Consider for dialysis if unable to achieve diuresis</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 23 year old man has been brought to the ED with a single stab wound to the left side of\nthe chest. Immediate FAST scan shows the following image.","parts":[{"id":"a","label":"Part A","prompt":"What pathology is demonstrated? (1 mark) Very shortly after arrival, the patient becomes unresponsive and has no palpable pulse."},{"id":"b","label":"Part B","prompt":"List the steps in your performance of an ED thoracotomy on this patient. (8 marks) BLANK PAGE"}],"propPages":["asset:img93fd93bf2e5ab17e15"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pericardial effusion (blood)</div><div class=\"answer-line\">[pericardial tamponade is NOT demonstrated per se]</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pt to be intubated</div><div class=\"answer-line\">Non-sterile procedure / PPE</div><div class=\"answer-line\">Incision – need location and extent</div><div class=\"answer-line\">Division of chest wall with appropriate scissors / gigli saw</div><div class=\"answer-line\">Rib spreaders</div><div class=\"answer-line\">identification of pericardium and phrenic nerve</div><div class=\"answer-line\">incision pericardium to release tamponade</div><div class=\"answer-line\">repair myocardial laceration if possible</div><div class=\"answer-line\">(will accept either clam-shell or left lateral thoracotomy – details will need to match chosen</div><div class=\"answer-line\">technique)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":28,"title":"","stemText":"A 6 year old boy has been brought to the ED after falling off a swing. He landed on his head and was initially unconscious for a brief period. He complained of neck pain and hence an x- ray of his cervical spine was performed. The image is given below.","parts":[{"id":"a","label":"Part A","prompt":"Give your overall interpretation of the xray. Include the findings that support your interpretation. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 possible clinical indications for further imaging of this child’s cervical spine.\n(3 marks) The child is mildly confused on initial examination (GCS 14)."},{"id":"c","label":"Part C","prompt":"List 6 features of your examination that would warrant investigation with a CT head\nscan. (6 marks)"}],"propPages":["asset:img4069ad7fd1081021e1","asset:img6803404cabd960c5df","asset:img5bd8d3f7db1c773c48","asset:imgf3e1dbaeddfd0ec66f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Normal xray</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Pseudosubluxation C2/3 and C3/4</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Normal Swischuk line</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Neurological abnormalities</div><div class=\"answer-line\">Inability to move neck</div><div class=\"answer-line\">Severe prolonged pain despite analgesia and time</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Multiple vomits</div><div class=\"answer-line\">Failure to return to GCS 15 at 2 hours</div><div class=\"answer-line\">Signs of skull vault fracture (including large boggy haematoma)</div><div class=\"answer-line\">Signs BOS fracture</div><div class=\"answer-line\">Focal neurological abnormalities</div><div class=\"answer-line\">Anterograde amnesia</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":29,"title":"","stemText":"A 65 year old man presents with sudden onset of painless visual loss in the right eye.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table with possible diagnoses and one relevant cardinal examination finding that will discriminate the"},{"id":"b","label":"Part B","prompt":"List 4 investigations that you might do in the ED for this patient. Provide justification\nfor each. (4 marks) Justification Investigation"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Diagnosis</td></tr><tr><td>Retinal detachment</td><td>Retinal curtain on fundoscopy</td></tr><tr><td>Retinal arterial occlusion / CRAO</td><td>Pale retina, possible embolus observed /</td></tr><tr><td colspan=\"2\">arteriolar cut off</td></tr><tr><td>CRVO</td><td>“blood and thunder retina”</td></tr><tr><td>Optic neuritis (eg MS, GCA)</td><td>RAPD / papillitis</td></tr><tr><td>Vitreous haemorrhage</td><td>Inability to visualise retina, blood posterior</td></tr><tr><td colspan=\"2\">chamber</td></tr><tr><td colspan=\"2\">2.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>ECG</td><td>Look for AF as embolic source for CRAO</td></tr><tr><td>BSL</td><td>Diabetic patients get vitreous haemorrhage</td></tr><tr><td>MRI</td><td>For MS if considering in optic neuritis</td></tr><tr><td>ESR</td><td>Raised in GCA</td></tr><tr><td>Others possible here</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":30,"title":"","stemText":"A 35 year old diabetic woman has presented to the ED with left flank pain and fever.\nA CT scan has been performed.","parts":[{"id":"a","label":"Part A","prompt":"Give your interpretation of the CT scan, supported by the relevant radiological evidence. (3 marks) The patient’s vital signs are:\n\nGCS\nPulse 120 /min\n\nBP\n75/40 mmHg\n\nTemp\n39.5 degrees\n\nRR\n/min O2 sats 99% room air"},{"id":"b","label":"Part B","prompt":"List your management steps in the ED. Include doses and end-points where appropriate. (8 marks)"}],"propPages":["asset:imgece02056c2589101af"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Emphysematous pyelonephritis</td></tr><tr><td>-</td><td>Enlarged left kidney</td></tr><tr><td>-</td><td>Air in kidney</td></tr><tr><td>-</td><td>Surrounding fat stranding</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>-</td><td>End points systolic BP &gt;100mmHg</td></tr><tr><td>-</td><td>Pulse &lt;100 (1 mark)</td></tr><tr><td>-</td><td>Repeat if needed</td></tr><tr><td colspan=\"2\">Early CVL – noradrenaline 1-40mcg/min with above goals, begin when CVP approaching</td></tr><tr><td colspan=\"2\">12cmH2O (2 marks)</td></tr><tr><td colspan=\"2\">IV Abs(1 mark)</td></tr><tr><td>-</td><td>Many options OK but must cover gram negs well</td></tr><tr><td>-</td><td>Eg amp and gent / pip-taz with doses</td></tr><tr><td colspan=\"2\">Management of BSLs with insulin sliding scale (1 mark)</td></tr><tr><td colspan=\"2\">Urgent urological referral, may need nephrectomy (1 mark)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
